R=[
(2950,"चिपोटले ग्लेज़ वाले मिनी मीट लोफ़","इन मीट लोफ़ में चिपोटले चिली पाउडर के ग्लेज़ से तीखा अंदाज़ आता है। अलग-अलग हिस्सों में बने चिपोटले ग्लेज़ वाले मिनी मीट लोफ़ बनाने और परोसने में आसान हैं।","2","1 मिनी मीट लोफ़",
["2 स्प्रिंग अनियन (हरे प्याज़)","3 कलियाँ लहसुन","1/2 छोटा चम्मच चिपोटले चिली पाउडर","2 बड़े चम्मच बिना नमक वाला केचप","1/2 पाउंड बीफ़ कीमा, 10% वसा वाला","1/2 कप पैंको ब्रेड क्रम्ब्स","1/2 छोटा चम्मच काली मिर्च","1/8 छोटा चम्मच नमक"],
["ओवन को 400° F पर पहले से गरम करें और ओवन रैक को सबसे ऊपरी स्थिति में रखें। स्प्रिंग अनियन के सिरे काटकर पतला स्लाइस करें, सफ़ेद हिस्सों को हरे हिस्सों से अलग रखें। सफ़ेद हिस्सों को बारीक काट लें। लहसुन की कली को चाकू के चपटे हिस्से से दबाएँ ताकि छिलका फट जाए। लहसुन का छिलका उतारकर बारीक काट लें।","एक छोटे कटोरे में केचप और 1/2 छोटा चम्मच चिपोटले चिली पाउडर मिलाकर अलग रख दें।","एक मध्यम कटोरे में बीफ़, स्प्रिंग अनियन के सफ़ेद हिस्से, कटा लहसुन, पैंको, काली मिर्च, नमक और बचा हुआ 1/2 छोटा चम्मच चिपोटले चिली पाउडर मिलाएँ।","बीफ़ के मिश्रण से दो लोफ़ बनाएँ। उन्हें नॉनस्टिक स्प्रे लगी बेकिंग शीट पर रखें।","मीट लोफ़ के लगभग पूरी तरह पकने तक, करीब 15 मिनट, बेक करें।","मीट लोफ़ पर केचप का मिश्रण ब्रश से लगाएँ। 4 से 8 मिनट के लिए वापस ओवन में रखें या जब तक मीट लोफ़ अंदर तक पककर 160° F के अंदरूनी तापमान तक न पहुँच जाएँ।","परोसने से पहले कटे हुए स्प्रिंग अनियन के हरे हिस्सों से सजाएँ।"],
["लोफ़ को अलग-अलग लोफ़ पैन में भी पकाया जा सकता है।","यदि आपके स्थानीय किराना स्टोर में बिना नमक वाला केचप उपलब्ध न हो, तो उसे ऑनलाइन मँगाने पर विचार करें।","बाद में झटपट व्यंजन के लिए फ्रीज़ करने हेतु रेसिपी को दोगुना करके ज़्यादा बनाएँ।"],
["3 मांस","1 स्टार्च","1/2 सब्ज़ी, कम पोटैशियम"]),
(2951,"साउथवेस्ट टूना सलाद","एरिज़ोना क्षेत्र का दक्षिण-पश्चिमी खाना, स्पैनिश और मैक्सिकन प्रभावों पर आधारित, अपना एक जीवंत व्यक्तित्व रखता है। एरिज़ोना की एलेन ने अपने पाक कौशल का इस्तेमाल करके हलापेनो के तीखेपन वाला किडनी के अनुकूल साउथवेस्ट टूना सलाद बनाया।","2","3/4 कप",
["1/4 कप मेयोनेज़","2 ताज़ी हलापेनो मिर्च","1/2 मध्यम खीरा","2 हरे प्याज़","1 बड़ा चम्मच ताज़ी धनिया पत्ती","1 बड़ा चम्मच ताज़ा नींबू (लाइम) का रस","5 औंस डिब्बाबंद कम सोडियम वाला, पानी में पैक टूना"],
["हलापेनो मिर्च के बीज निकालकर बारीक काट लें। खीरे के बीज निकालकर काटें; हरे प्याज़ और धनिया पत्ती को काट लें।","मध्यम कटोरे में मेयोनेज़, हलापेनो मिर्च और नींबू (लाइम) का रस मिलाएँ।","पानी निथारा हुआ टूना डालकर चलाएँ। अच्छी तरह मिलाएँ।","खीरा और हरे प्याज़ डालें। खाने तक ठंडा रखें।","साउथवेस्ट टूना सलाद का एक स्कूप सलाद पत्ते पर या अपनी पसंद के बैगल या ब्रेड पर परोसें। चाहें तो कटी हुई धनिया पत्ती से सजाएँ।"],
[],
["2-1/2 मांस","1 सब्ज़ी, कम पोटैशियम","2 वसा"]),
(2953,"तोरी (ज़ुकीनी) फ्रिटाटा","तोरी सबसे बहुमुखी सब्ज़ियों में से एक है। आप तोरी की ब्रेड या मफ़िन बना सकते हैं, उसे कच्चा सलाद में डाल सकते हैं, भाप में पका सकते हैं, उबाल सकते हैं, माइक्रोवेव कर सकते हैं या तल सकते हैं, या आप कैलिफ़ोर्निया की डीवीटा डाइटिशियन जेसिका द्वारा भेजा गया तोरी फ्रिटाटा आज़मा सकते हैं। यह किडनी के अनुकूल रेसिपी ज़रूर पसंद आएगी!","9","1 टुकड़ा",
["2 मध्यम तोरी (ज़ुकीनी)","1 मध्यम प्याज़","1/4 कप अजमोद (पार्सले)","1 कली लहसुन","4 बड़े अंडे","1 कप बिस्कुट बेकिंग मिक्स","1/2 कप कद्दूकस किया पारमेसन चीज़","1/4 कप कैनोला तेल","1/2 छोटा चम्मच सूखा मार्जोरम","1/4 छोटा चम्मच काली मिर्च"],
["ओवन को 350° F पर पहले से गरम करें। तोरी को कद्दूकस करें; प्याज़ और अजमोद (पार्सले) को काटें; लहसुन को बारीक काट लें। अंडों को हल्का फेंट लें।","एक बड़े कटोरे में सारी सामग्री मिलाएँ और अच्छी तरह चलाएँ।","चिकनाई लगे 11 x 7 इंच के पैन या 9 इंच की कास्ट आयरन कड़ाही में डालें। जमने और हल्का भूरा होने तक 30 से 35 मिनट बेक करें।","9 टुकड़ों में काटें और परोसें।"],
["बचा हुआ अगले दिन भी बढ़िया लगता है! फ्रिज में रखें और ओवन या माइक्रोवेव में दोबारा गरम करें।","गरम या ठंडा, दोनों तरह से अच्छा लगता है!!"],
["1/2 मांस","1/2 स्टार्च","1/2 सब्ज़ी, कम पोटैशियम","1 वसा"]),
(2956,"छोले और ब्राउन राइस सलाद","ब्राउन राइस, छोले, अजमोद (पार्सले), शिमला मिर्च, खीरे और थोड़े फ़ेटा चीज़ का मेल, यह छोले और ब्राउन राइस सलाद स्वाद और फाइबर दोनों में भरपूर है।","6","3/4 कप",
["1/2 कप ब्राउन राइस, सूखा","15 औंस डिब्बाबंद छोले","1/2 कप ताज़ा अजमोद (पार्सले)","1/4 कप ताज़ा नींबू का रस","3 बड़े चम्मच ऑलिव ऑयल","1/2 छोटा चम्मच काली मिर्च","1 मध्यम लाल शिमला मिर्च","1 रोमा टमाटर","1/2 मध्यम लाल प्याज़","1 छोटा इंग्लिश खीरा","2 बड़े चम्मच चूरा किया फ़ेटा चीज़"],
["ब्राउन राइस को निर्देशों के अनुसार पकाएँ और अलग रख दें।","छोले को धोकर पानी निथार लें। अजमोद (पार्सले) को काट लें।","एक बड़े कटोरे में अजमोद (पार्सले), नींबू का रस, ऑलिव ऑयल और काली मिर्च डालें। विनेग्रेट बनाने के लिए इन्हें फेंटकर मिलाएँ।","शिमला मिर्च, टमाटर, प्याज़ और खीरे को काटकर विनेग्रेट वाले कटोरे में डालें।","पके चावल और छोले डालें, मिलाने के लिए चलाएँ।","ऊपर से चूरा किया फ़ेटा चीज़ डालें।","स्वाद पूरी तरह विकसित होने के लिए परोसने से 30 मिनट से एक घंटा पहले रखा रहने दें।"],
["ठंडा या सामान्य तापमान पर परोसें।","इस रेसिपी को पहले से बनाकर फ्रिज में 3 दिन तक रखा जा सकता है।"],
["2 स्टार्च","1/2 सब्ज़ी, मध्यम पोटैशियम"]),
(2959,"मैक्सिकन मीटबॉल सूप (अल्बोंडिगास)","मैक्सिकन मीटबॉल सूप इस लोकप्रिय मैक्सिकन सूप का कम सोडियम वाला, किडनी के अनुकूल संस्करण है।","6","3 मीटबॉल + 1/3 कप सब्ज़ियों के साथ 3/4 कप तरल",
["1 मध्यम प्याज़","1 बड़ी गाजर","1 छोटी तोरी (ज़ुकीनी)","1/2 कप धनिया पत्ती","48 औंस कम सोडियम वाला चिकन ब्रॉथ","2 छोटे चम्मच पिसा जीरा","4 औंस डिब्बाबंद कटी हरी मिर्चें","4 औंस बिना नमक वाली टमाटर सॉस","2 बड़े चम्मच नींबू (लाइम) का रस","1 छोटा चम्मच पैपरिका","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच लाल मिर्च (काएन चिली पेपर) (स्वादानुसार समायोजित करें)","1 बड़ा अंडा","1 छोटा चम्मच बारीक कटा लहसुन","1 पाउंड बीफ़ कीमा","1/2 कप पका सफ़ेद चावल","1/2 छोटा चम्मच काली मिर्च"],
["ओवन को 400° F पर पहले से गरम करें। प्याज़ के 1/4 हिस्से को बारीक काटकर मीटबॉल बनाने के समय तक अलग रख दें। बचे प्याज़, गाजर और तोरी को 3/4-इंच के टुकड़ों में काटें। धनिया पत्ती को काट लें।","ब्रॉथ को बर्तन में डालकर मध्यम आँच पर गरम करें। कटी हुई सब्ज़ियाँ, 1 छोटा चम्मच जीरा, हरी मिर्चें, टमाटर सॉस, 1/4 कप धनिया पत्ती, नींबू (लाइम) का रस, पैपरिका, नमक और लाल मिर्च (काएन पेपर) डालें। बर्तन को ढक दें और आँच धीमी कर दें।","एक मध्यम कटोरे में अंडा, 1 छोटा चम्मच जीरा और लहसुन मिलाएँ। बीफ़ कीमा, पका चावल और अलग रखा बारीक कटा प्याज़ डालें। मिलने तक मिलाएँ।","मिश्रण से लगभग 1-1/2-इंच व्यास के मीटबॉल बनाएँ, कुल 18 मीटबॉल। उन्हें पार्चमेंट लगी बेकिंग शीट पर रखें और भूरा होने और अंदर तक पकने तक 20 मिनट बेक करें। मीटबॉल को 5 मिनट ठंडा होने दें।","मीटबॉल और बची हुई 1/4 कप धनिया पत्ती सूप में डालें और परोसने से पहले 10 मिनट धीमी आँच पर पकाएँ।"],
["चाहें तो मीटबॉल को बेक करने की जगह ब्रॉथ में पकाया जा सकता है, लेकिन इससे ब्रॉथ धुँधला हो जाएगा। कच्चे मीटबॉल को गरम ब्रॉथ में डालें, ढकें और मध्यम आँच पर 30 मिनट पकाएँ।"],
["2-1/2 मांस","1/2 स्टार्च","1 सब्ज़ी, मध्यम पोटैशियम"]),
(2960,"क्रॉक-पॉट® रोस्टेड लेमन चिकन","कल्पना कीजिए कि आप काम से या दिन भर बाहर रहने के बाद घर आते हैं और दरवाज़ा खोलते ही रसीले लेमन चिकन की खुशबू आती है, और वह रात के खाने के लिए परोसने को तैयार है। यह केवल एक सपना नहीं है, यदि आप ओहायो की डीवीटा डाइटिशियन डीएना की किडनी के अनुकूल यह क्रॉक-पॉट® लेमन रोस्टेड चिकन रेसिपी आज़माएँ।","8","1 चिकन ब्रेस्ट",
["1 बड़ा चम्मच ऑलिव ऑयल","2 कलियाँ लहसुन, बारीक कटी","1 छोटा चम्मच ओरेगैनो","2 पाउंड चिकन ब्रेस्ट, हड्डी और त्वचा सहित","13 औंस डिब्बाबंद कम किए गए सोडियम वाला चिकन ब्रॉथ","3 बड़े चम्मच नींबू का रस"],
["बड़ी कड़ाही में तेल गरम करें।","लहसुन और ओरेगैनो डालें।","चिकन ब्रेस्ट डालें और सभी तरफ़ से भूरा करें।","चिकन को क्रॉक-पॉट में रखें और चिकन ब्रॉथ डालें।","धीमी आँच की सेटिंग पर 6 से 8 घंटे पकाएँ।","पकाने के आख़िरी घंटे में नींबू का रस डालें।"],
["इस भोजन को चावल, हरी बीन्स, फ्रेंच ब्रेड, मार्जरीन या मक्खन की एक सर्विंग और मिठाई के रूप में बेक किए सेब के साथ पूरा करें।","बचे हुए चिकन ब्रेस्ट को अगले दिन दोपहर के भोजन के लिए चिकन सलाद या सैंडविच में इस्तेमाल करें।","ऐसा कम किए गए सोडियम वाला ब्रॉथ ढूँढें जिसमें प्रति 1 कप सर्विंग 500 मिलीग्राम या उससे कम सोडियम हो। अनुशंसित ब्रांड में Health Valley® No Salt, Fat Free Chicken Broth (1-800-423-4846), Kitchen Basics® Natural Chicken Stock और Swanson® 50% Less Sodium Chicken Broth शामिल हैं। कम सोडियम वाला ब्रॉथ भी एक अच्छा विकल्प है। इसमें प्रति कप 140 मिलीग्राम से कम सोडियम होता है। ऐसे कम सोडियम वाले ब्रॉथ से बचें जिनमें पोटैशियम क्लोराइड हो, उसमें पोटैशियम बहुत ज़्यादा होता है।","यदि आप प्रोटीन-सीमित आहार पर हैं, तो अपने व्यक्तिगत आहार के लिए सही हिस्से के आकार के बारे में अपने डाइटिशियन से सलाह लें।"],
["3-1/2 मांस"]),
(2961,"रैवियोली और तोरी (ज़ुकीनी)","पास्ता के व्यंजन आपके आहार में सामान्य मांस-आधारित भोजन की जगह विविधता लाने का बढ़िया तरीका हैं। डीवीटा डाइटिशियन सैंड्रा की रैवियोली और तोरी की किडनी के अनुकूल रेसिपी शुरू से 20 मिनट या उससे कम में तैयार की जा सकती है। इस व्यंजन की ख़ास बात यह है कि रैवियोली को ज़्यादा न पकाएँ, उसमें वह अल डेंटे गुण बना रहना चाहिए जो इतालवी लोगों को पसंद है। अल डेंटे का शाब्दिक अनुवाद \"दाँतों के साथ\" है, इस स्वादिष्ट रेसिपी में अपने दाँत गड़ाइए।","4","1 कप",
["9 औंस जमी हुई बीफ़ रैवियोली","2 कप तोरी (ज़ुकीनी)","3 हरे प्याज़","1 मध्यम लाल शिमला मिर्च","1/2 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच सूखी तुलसी (बेसिल) की पत्तियाँ","1/8 छोटा चम्मच काली मिर्च","1/4 कप कम किए गए सोडियम वाला चिकन ब्रॉथ"],
["तोरी को जूलियन शैली में काटें और हरे प्याज़ को स्लाइस करें; शिमला मिर्च को मोटा-मोटा काट लें।","रैवियोली को पैकेट पर बताए अनुसार पकाएँ।","एक बड़ी नॉनस्टिक कड़ाही पर कुकिंग स्प्रे करें और तेज़-मध्यम आँच पर गरम करें।","तोरी, हरे प्याज़, शिमला मिर्च, लहसुन पाउडर, तुलसी (बेसिल) और काली मिर्च डालें। 3 से 5 मिनट तक सब्ज़ियों के हल्का कुरकुरा रहते हुए नरम होने तक पकाएँ।","रैवियोली का पानी निथारें, ब्रॉथ डालें और सब्ज़ियों के मिश्रण में मिलाएँ।","कड़ाही को ढककर मध्यम-धीमी आँच पर 5 मिनट और या अच्छी तरह गरम होने तक पकाएँ। बीच-बीच में चलाएँ, ध्यान रखें कि रैवियोली न टूटे।"],
["यदि सब्ज़ियाँ पहले से तैयार हों, तो यह एक झटपट और आसान भोजन है जिसे कोई भी बना सकता है।","यह टॉस्ड सलाद और फ्रेंच ब्रेड के साथ अच्छा लगता है।","रैवियोली के अन्य प्रकार आज़माएँ, जमी हुई या ताज़ी, बीफ़ या चिकन वाली।"],
["1-1/2 मांस","1-1/2 स्टार्च","1 सब्ज़ी, मध्यम पोटैशियम"]),
(2962,"पैकेट वाले से बेहतर राइस पिलाफ़","शुरू से बना खाना स्वाद और पोषक तत्वों दोनों में हमेशा पैकेट वाले खाने से बेहतर होता है। कैलिफ़ोर्निया की डीवीटा डाइटिशियन ब्रुक ने यह किडनी के अनुकूल, कम सोडियम वाला राइस पिलाफ़ बनाया। यह बनाने में आसान है और ख़ासकर पैकेट वाले राइस पिलाफ़ की तुलना में एक उत्कृष्ट विकल्प है।","6","3/4 कप",
["2 औंस वर्मीसेली नूडल्स, कच्चे","2 बड़े चम्मच बिना नमक का मक्खन","1 कप पारबॉइल्ड चावल, कच्चे","2 कप पानी","1 बड़ा चम्मच Mrs. Dash® ऑनियन एंड हर्ब सीज़निंग ब्लेंड","1 छोटा चम्मच चिकन-फ़्लेवर बाउलन दाने"],
["कड़ाही में मध्यम आँच पर 1 बड़ा चम्मच मक्खन पिघलाएँ।","वर्मीसेली नूडल्स को 2-इंच के टुकड़ों में तोड़ें और बार-बार चलाते हुए नूडल्स के भूरा होने तक पकाएँ।","बचा हुआ मक्खन और चावल डालें। मिलाने के लिए चलाएँ।","कड़ाही में पानी, Mrs. Dash हर्ब सीज़निंग और चिकन बाउलन दाने डालें। सामग्री को मिलाने के लिए चलाएँ।","ढककर उबाल आने दें। आँच धीमी करें और 20 मिनट धीमी आँच पर पकाएँ। ढक्कन न हटाएँ।","आँच बंद करें और ढके हुए 5 मिनट और रहने दें।","काँटे से फुलाएँ और परोसें।"],
["वर्मीसेली की जगह एंजेल हेयर या पतले स्पैघेटी नूडल्स इस्तेमाल किए जा सकते हैं।","तुलना के लिए, नमक वाले मक्खन या मार्जरीन से बना पैकेट वाला राइस पिलाफ़ प्रति 1/2 कप सर्विंग 400 से 650 मिग्रा सोडियम रखता है।","कुछ कम या घटे हुए सोडियम वाले बाउलन दानों या क्यूब्स में नमक की जगह पोटैशियम क्लोराइड होता है। यदि आप कम पोटैशियम वाले आहार पर हैं, तो इनकी सलाह नहीं दी जाती।","अतिरिक्त हिस्सों को फ्रीज़ करें और बाद में बहुत झटपट स्टार्च वाली साइड डिश के लिए माइक्रोवेव में दोबारा गरम करें।"],
["2 स्टार्च","1/2 वसा"]),
(2964,"मक्का और चीज़ के गोले","एक डायलिसिस मरीज़ की माँ द्वारा बनाए गए, मक्का और चीज़ के गोले एक चीज़ वाला नाश्ता हैं जो आपको संतुष्ट रखेगा और साथ ही किडनी आहार का भी ध्यान रखेगा।","8","4 गोले",
["2 कप जमा हुआ पीला मक्का (कॉर्न)","1 हरी मिर्च","2 बड़े चम्मच धनिया पत्ती","1/2 कप कॉटेज चीज़","4 स्लाइस सफ़ेद ब्रेड","1/2 कप मैदा (ऑल-पर्पज़ व्हाइट फ्लोर)","1 छोटा चम्मच चिली पाउडर","1 छोटा चम्मच जीरा पाउडर","1 छोटा चम्मच धनिया पाउडर","1/4 छोटा चम्मच नमक","2 कप वनस्पति तेल"],
["मक्का को पिघलने दें। हरी मिर्च और धनिया पत्ती को बारीक काट लें।","मिक्सिंग बाउल में चीज़ और पिघला हुआ मक्का मिलाएँ।","ब्रेड के स्लाइस को पानी में भिगोएँ और पानी निचोड़ दें ताकि ब्रेड सूखी हो जाए। इसे मक्का और चीज़ के मिश्रण में डालें। मैदा, सूखे मसाले और धनिया पत्ती डालें। हल्के हाथ से मिलाएँ।","बड़े सॉसपैन में तेल गरम करें। बड़े चम्मच से मक्का और चीज़ के मिश्रण से छोटे गोले बनाएँ और हर गोले को गरम तेल में डालें। सुनहरा भूरा होने तक पकाएँ।","गोलों को तेल से निकालें और अतिरिक्त तेल सोखने के लिए किचन नैपकिन लगी ट्रे में रखें।","गरमागरम धनिया की चटनी के साथ परोसें।"],
["यदि उपलब्ध हो, तो कॉटेज चीज़ की जगह चूरा किया पनीर इस्तेमाल करें।","पनीर बिना पका चीज़ है जो दूध को नींबू के रस या किसी अन्य खट्टे खाद्य पदार्थ से फाड़कर बनता है। विकल्पों में ड्राई कर्ड कॉटेज चीज़, फार्मर्स चीज़, केसो ब्लैंको या केसो फ्रेस्को शामिल हैं। हिस्सा सीमित है क्योंकि इस डेयरी उत्पाद में फॉस्फोरस होता है।"],
["2 स्टार्च","1/2 सब्ज़ी, मध्यम पोटैशियम","2 वसा"]),
(2965,"टमाटर बोट ऐपेटाइज़र","टमाटर और फलियाँ ज़्यादातर किडनी आहारों में \"सीमित\" सूची में हैं, लेकिन इन सेहतमंद सामग्री की छोटी मात्रा को शामिल किया जा सकता है, जबकि पोटैशियम और फॉस्फोरस को नियंत्रण में रखा जाता है। अतिरिक्त पोषक तत्वों के अलावा, डीवीटा डाइटिशियन क्रिस्टीन के टमाटर बोट ऐपेटाइज़र की एक सर्विंग में 2.5 ग्राम फाइबर होता है।","8","1 टमाटर का आधा हिस्सा",
["4 सख़्त रोमा टमाटर","1 बड़ा चम्मच एक्स्ट्रा वर्जिन ऑलिव ऑयल","1 छोटा चम्मच काली मिर्च","1 छोटा चम्मच लहसुन पाउडर","1 छोटा चम्मच बिना नमक वाला हर्ब सीज़निंग ब्लेंड","15 औंस डिब्बाबंद छोले","1/2 नींबू","1 छोटा चम्मच रेड वाइन सिरका","8 ताज़ी पुदीने की पत्तियाँ"],
["टमाटरों को आधा काटें और \"नावें\" बनाने के लिए गूदा निकालकर फेंक दें।","टमाटर की नावों के अंदर 1/2 बड़ा चम्मच ऑलिव ऑयल, 1/2 छोटा चम्मच काली मिर्च, 1/2 छोटा चम्मच लहसुन पाउडर और 1/2 छोटा चम्मच बिना नमक वाली सीज़निंग हल्के से छिड़कें।","छोले को धोकर पानी निथार लें। एक कटोरे में छोले, बचा ऑलिव ऑयल, मसाले, 1/2 नींबू का रस और सिरका डालें। मिलाएँ।","छोले के मिश्रण को चम्मच से टमाटर के कपों में भरें। पुदीने की पत्ती से सजाएँ।","फ्रिज में रखें और ठंडा परोसें।"],
["यदि चाहें तो हर टमाटर के आधे हिस्से की जगह 1/4 मध्यम लाल शिमला मिर्च इस्तेमाल करें। पोटैशियम 12 मिग्रा कम होता है।","छोले, जिन्हें काबुली चना भी कहा जाता है, और अन्य फलियों में पोटैशियम और फॉस्फोरस ज़्यादा होता है। फाइबर बढ़ाने के लिए सेहतमंद किडनी आहार में थोड़ी मात्रा शामिल की जा सकती है। हर नाव में लगभग 1/6 कप छोले होते हैं।","टमाटर का गूदा निकाल देने से पोटैशियम की मात्रा घट जाती है।"],
["1/2 स्टार्च","1/2 सब्ज़ी, मध्यम पोटैशियम","1/2 वसा"]),
]
